create table if not exists public.store_pix_configs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,store_id uuid not null references public.stores(id) on delete cascade,pix_key text not null,pix_key_type text not null default 'OTHER',merchant_name text not null,merchant_city text not null,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id)); alter table public.store_pix_configs enable row level security; create policy store_pix_configs_read on public.store_pix_configs for select to authenticated using(private.has_store_access(store_id)); create policy store_pix_configs_manage on public.store_pix_configs for all to authenticated using(private.has_store_access(store_id) and private.has_feature(tenant_id,'settings.edit','MANAGE')) with check(private.has_store_access(store_id) and private.has_feature(tenant_id,'settings.edit','MANAGE'));